                exists(root, ".codex-plugin/agents/user-codex-agent.md").shouldBeTrue()
                exists(root, ".codex-plugin/plugin.json").shouldBeFalse()

                exists(root, ".opsx/cache").shouldBeFalse()
                exists(root, ".opsx/config.json").shouldBeFalse()
            } finally {
                cleanupDir(root)
            }
        }
