        test("progress bar handles zero total") {
            val bar = Style.progressBar(0, 0)
            bar shouldContain "0%"
        }

        test("elapsed formats seconds") {
            Style.elapsed(30) shouldBe "30s"
        }

        test("elapsed formats minutes") {
